 protect();q=read(R/'13_numerical_qualification/QUALIFICATION_DECISION.json');f=np.load(R/'13_numerical_qualification/COMPARISON_FIELDS.npz');a=f['M1'];b=f['M2'];x=f['xyz'];w=f['area'];m=f['common'];r=f['region'];ids=f['source_ids'];aa=a[m];bb=b[m];ww=w[m];xx=x[m];d=bb-aa;ha=f['high_M1'][m];hb=f['high_M2'][m];intersection=float(ww[ha&hb].sum());precision=intersection/float(ww[hb].sum());recall=intersection/float(ww[ha].sum());ca=np.average(xx[ha],weights=ww[ha],axis=0);cb=np.average(xx[hb],weights=ww[hb],axis=0);maps=[read(R/'10_source_mapping'/l/'MAPPING_AUDIT.json') for l in ['M1','M2']];checks=[read(R/'09_tensor_recovery'/f'{l}_INDEPENDENT_TENSOR_RECEIPT.json') for l in ['M1','M2']];natives=[read(R/fol/'SOLVE_COMPLETE.json') for fol in ['06_native_M1','07_native_M2']];raw_area=np.load(R/'01_frozen_protocol/source/area.npy');assert np.array_equal(raw_area,w)
